import { useMemo, useState } from "react";
import {
  Button,
  Card,
  NativeSelect,
  PageHeader,
  RecordList,
  StatusPill,
  Typography,
} from "@autograph/components";
import {
  RecordDetailPanel,
  RecordListDetailLayout,
} from "@autograph/compositions";

type Severity = "critical" | "high" | "watch";
type Product = {
  id: string;
  name: string;
  sku: string;
  location: string;
  severity: Severity;
  onHand: number;
  safetyStock: number;
  incoming: number;
  daysCover: number;
  supplier: string;
  leadTime: string;
  minimumOrder: number;
  unitCost: string;
  suggested: number;
};

const products: Product[] = [
  { id: "p-101", name: "Organic Whole Milk, 1L", sku: "DRY-1042", location: "Downtown", severity: "critical", onHand: 4, safetyStock: 24, incoming: 0, daysCover: 0.6, supplier: "North Valley Dairy", leadTime: "2 days", minimumOrder: 24, unitCost: "$2.18", suggested: 48 },
  { id: "p-102", name: "Free-range Eggs, 12 pack", sku: "DRY-2066", location: "Downtown", severity: "high", onHand: 11, safetyStock: 30, incoming: 12, daysCover: 1.4, supplier: "Meadow Farms", leadTime: "3 days", minimumOrder: 24, unitCost: "$3.42", suggested: 24 },
  { id: "p-103", name: "Sparkling Water, Lime 8 pack", sku: "BEV-3310", location: "Riverside", severity: "high", onHand: 8, safetyStock: 36, incoming: 0, daysCover: 1.1, supplier: "Clear Spring Beverage", leadTime: "4 days", minimumOrder: 16, unitCost: "$4.10", suggested: 32 },
  { id: "p-104", name: "Sourdough Sandwich Loaf", sku: "BAK-8104", location: "Riverside", severity: "watch", onHand: 17, safetyStock: 22, incoming: 10, daysCover: 2.8, supplier: "Union Street Bakery", leadTime: "1 day", minimumOrder: 10, unitCost: "$2.85", suggested: 10 },
  { id: "p-105", name: "Avocado, Hass each", sku: "PRD-1421", location: "North Market", severity: "critical", onHand: 6, safetyStock: 40, incoming: 20, daysCover: 0.7, supplier: "Pacific Fresh Produce", leadTime: "2 days", minimumOrder: 30, unitCost: "$1.08", suggested: 60 },
];

const severityLabel: Record<Severity, string> = { critical: "Critical", high: "High", watch: "Watch" };
const severityTone: Record<Severity, "danger" | "warning" | "neutral"> = { critical: "danger", high: "warning", watch: "neutral" };

export default function StockExceptions() {
  const [location, setLocation] = useState("all");
  const [severity, setSeverity] = useState("all");
  const [selectedId, setSelectedId] = useState<string | undefined>("p-101");
  const [mocked, setMocked] = useState<Record<string, boolean>>({});

  const filtered = useMemo(() => products.filter((product) =>
    (location === "all" || product.location === location) &&
    (severity === "all" || product.severity === severity)
  ), [location, severity]);
  const selected = filtered.find((product) => product.id === selectedId);

  function applyFilters(nextLocation: string, nextSeverity: string) {
    const next = products.filter((product) =>
      (nextLocation === "all" || product.location === nextLocation) &&
      (nextSeverity === "all" || product.severity === nextSeverity)
    );
    setSelectedId((current) => next.some((product) => product.id === current) ? current : next[0]?.id);
  }

  const list = (
    <RecordList
      ariaLabel="Low-stock exceptions"
      heading="Low-stock products"
      summary={`${filtered.length} ${filtered.length === 1 ? "exception" : "exceptions"}`}
      selectedId={selected?.id}
      onSelect={setSelectedId}
      emptyState={
        <div>
          <Typography variant="body-strong">No exceptions match these filters</Typography>
          <Typography variant="body" tone="muted" className="mt-[var(--space-1)] mb-0">Try another location or severity. No product remains selected.</Typography>
        </div>
      }
      items={filtered.map((product) => ({
        id: product.id,
        primary: product.name,
        secondary: `${product.sku} · ${product.location} · ${product.onHand} on hand`,
        trailing: <StatusPill size="sm" label={severityLabel[product.severity]} tone={severityTone[product.severity]} />,
      }))}
    />
  );

  const detail = selected ? (
    <RecordDetailPanel
      className="h-full"
      title={selected.name}
      subtitle={`${selected.sku} · ${selected.location}`}
      status={{ label: severityLabel[selected.severity], tone: severityTone[selected.severity], detail: `${selected.daysCover} days cover` }}
      sections={[
        {
          id: "decision",
          title: "Stock decision",
          collapsible: false,
          items: [
            { type: "field", id: "on-hand", label: "On hand", value: `${selected.onHand} units` },
            { type: "field", id: "safety-stock", label: "Safety stock", value: `${selected.safetyStock} units` },
            { type: "field", id: "incoming", label: "Already incoming", value: selected.incoming ? `${selected.incoming} units` : "None" },
            { type: "field", id: "suggested", label: "Suggested order", value: `${selected.suggested} units` },
            { type: "note", id: "action", body: "action-slot" },
          ],
        },
        {
          id: "supplier",
          title: "Supplier details",
          defaultOpen: false,
          items: [
            { type: "field", id: "supplier", label: "Preferred supplier", value: selected.supplier },
            { type: "field", id: "lead-time", label: "Lead time", value: selected.leadTime },
            { type: "field", id: "minimum-order", label: "Minimum order", value: `${selected.minimumOrder} units` },
            { type: "field", id: "unit-cost", label: "Unit cost", value: selected.unitCost },
          ],
        },
      ]}
      renderItem={(item) => item.id === "action" ? (
        <Card className="my-[var(--space-3)]" title="Try replenishment">
          <Typography variant="body" tone="secondary" className="mt-0">Create a reversible mock order for {selected.suggested} units from {selected.supplier}. This will not contact the supplier or change inventory.</Typography>
          {mocked[selected.id] ? (
            <div aria-live="polite" className="grid gap-[var(--space-3)]">
              <StatusPill size="sm" tone="success" label="Mock replenishment prepared" />
              <Typography variant="body" className="m-0">Preview complete: {selected.suggested} units for {selected.name} from {selected.supplier}. No order was sent and stock remains unchanged.</Typography>
              <div><Button size="sm" intent="secondary" onClick={() => setMocked((state) => ({ ...state, [selected.id]: false }))}>Reset mock</Button></div>
            </div>
          ) : (
            <Button intent="primary" onClick={() => setMocked((state) => ({ ...state, [selected.id]: true }))}>Try mock replenishment</Button>
          )}
        </Card>
      ) : undefined}
    />
  ) : (
    <Card>
      <Typography variant="body-strong">Select an exception to review</Typography>
      <Typography variant="body" tone="muted" className="mb-0">Stock and supplier details will appear here.</Typography>
    </Card>
  );

  return (
    <main className="min-h-screen bg-[var(--color-bg-subtle)] p-[var(--space-5)] text-[var(--color-text-primary)]">
      <div className="mx-auto grid max-w-[var(--size-page-max)] gap-[var(--space-5)]">
        <PageHeader title="Stock Exceptions" subtitle="Review low-stock products and test a replenishment before taking action." />
        <section aria-label="Exception filters" className="flex flex-wrap items-end gap-[var(--space-3)]">
          <div className="w-[var(--size-filter-control)] max-w-full">
            <Typography variant="caption" tone="secondary" className="mb-[var(--space-1)]">Location</Typography>
            <NativeSelect ariaLabel="Filter by location" value={location} options={[{ value: "all", label: "All locations" }, { value: "Downtown", label: "Downtown" }, { value: "Riverside", label: "Riverside" }, { value: "North Market", label: "North Market" }]} onValueChange={(value) => { setLocation(value); applyFilters(value, severity); }} />
          </div>
          <div className="w-[var(--size-filter-control)] max-w-full">
            <Typography variant="caption" tone="secondary" className="mb-[var(--space-1)]">Severity</Typography>
            <NativeSelect ariaLabel="Filter by severity" value={severity} options={[{ value: "all", label: "All severities" }, { value: "critical", label: "Critical" }, { value: "high", label: "High" }, { value: "watch", label: "Watch" }]} onValueChange={(value) => { setSeverity(value); applyFilters(location, value); }} />
          </div>
          {(location !== "all" || severity !== "all") ? <Button size="sm" intent="ghost" onClick={() => { setLocation("all"); setSeverity("all"); setSelectedId((current) => products.some((product) => product.id === current) ? current : products[0].id); }}>Clear filters</Button> : null}
        </section>
        <RecordListDetailLayout list={list} detail={detail} hasSelection={Boolean(selected)} selectedId={selected?.id} onBack={() => setSelectedId(undefined)} backLabel="Back to exceptions" className="min-h-0" />
      </div>
    </main>
  );
}
